package net.moz.driver;
import android.Manifest;import android.app.Activity;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.webkit.*;import android.widget.Toast;import androidx.core.content.FileProvider;import java.io.File;import java.util.UUID;
public class MainActivity extends Activity {
 static final String BASE="https://moz.runasp.net";WebView web;String pendingTrip,pendingOwner,pendingEpoch;ValueCallback<Uri[]> fileCallback;Uri cameraUri;
 boolean trusted(String url){try{Uri u=Uri.parse(url);return "https".equals(u.getScheme())&&"moz.runasp.net".equals(u.getHost())&&(u.getPort()==-1||u.getPort()==443);}catch(Exception e){return false;}}
 @Override public void onCreate(Bundle state){super.onCreate(state);web=new WebView(this);web.setBackgroundColor(Color.rgb(13,12,22));setContentView(web);
 WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setGeolocationEnabled(false);s.setJavaScriptCanOpenWindowsAutomatically(false);
 CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.addJavascriptInterface(new Bridge(),"MozNative");
 web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){String url=r.getUrl().toString();if(trusted(url))return false;if("https".equals(r.getUrl().getScheme()))try{startActivity(new Intent(Intent.ACTION_VIEW,r.getUrl()));}catch(Exception ignored){}return true;}@Override public void onReceivedSslError(WebView v,SslErrorHandler h,android.net.http.SslError e){h.cancel();}});
 web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams params){if(!trusted(v.getUrl())){cb.onReceiveValue(null);return true;}if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=cb;cameraUri=null;
 Intent select=new Intent(Intent.ACTION_GET_CONTENT);select.setType("image/*");select.addCategory(Intent.CATEGORY_OPENABLE);Intent camera=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);Intent chooser=Intent.createChooser(select,"Fotografar ou selecionar comprovante");
 try{File dir=new File(getCacheDir(),"pod");dir.mkdirs();File f=File.createTempFile("moz-pod-",".jpg",dir);cameraUri=FileProvider.getUriForFile(MainActivity.this,"net.moz.driver.files",f);camera.putExtra(MediaStore.EXTRA_OUTPUT,cameraUri);camera.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);camera.setClipData(ClipData.newRawUri("comprovante",cameraUri));chooser.putExtra(Intent.EXTRA_INITIAL_INTENTS,new Intent[]{camera});}catch(Exception ignored){}
 try{startActivityForResult(chooser,12);}catch(Exception e){fileCallback.onReceiveValue(null);fileCallback=null;}return true;}});
 if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},21);web.loadUrl(BASE);}
 class Bridge {
 @JavascriptInterface public boolean canStartAuthorizedTracking(String epoch){return epoch!=null&&!epoch.equals(TrackingService.blockedEpoch)&&!epoch.equals(TrackingService.authorization(MainActivity.this).getString("blockedEpoch",""))&&!TrackingService.running&&pendingTrip==null;}
 @JavascriptInterface public void startAuthorizedTracking(String trip,String owner,String epoch){runOnUiThread(()->{if(!trusted(web.getUrl())||!canStartAuthorizedTracking(epoch))return;try{UUID.fromString(trip);UUID.fromString(owner);java.time.Instant.parse(epoch);}catch(Exception e){return;}pendingTrip=trip;pendingOwner=owner;pendingEpoch=epoch;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},20);return;}launchTracking();});}
 @JavascriptInterface public String pendingProofs(String owner,String trip){try{UUID.fromString(owner);UUID.fromString(trip);try(TrackingService.QueueDb db=new TrackingService.QueueDb(MainActivity.this)){return db.pending(owner,trip).toString();}}catch(Exception e){return "[]";}}
 @JavascriptInterface public boolean saveOfflineProof(String id,String owner,String trip,String epoch,String stage,String captured,boolean finish,String base64){
 try{UUID.fromString(id);UUID.fromString(owner);UUID.fromString(trip);UUID.fromString(stage);java.time.Instant.parse(captured);
 if(!TrackingService.previouslyAuthorized(MainActivity.this,owner,trip,epoch))return false;
 if(base64==null||base64.length()>28000000)return false;byte[] bytes=android.util.Base64.decode(base64,android.util.Base64.DEFAULT);if(bytes.length<4||bytes.length>20*1024*1024)return false;
 File dir=new File(getFilesDir(),"pending-pods");if(!dir.exists()&&!dir.mkdirs())return false;
 File file=new File(dir,id);if(file.exists())return false;
 try(java.io.FileOutputStream out=new java.io.FileOutputStream(file)){out.write(bytes);out.getFD().sync();}
 try(TrackingService.QueueDb db=new TrackingService.QueueDb(MainActivity.this)){db.addPod(id,owner,trip,stage,captured,file.getAbsolutePath(),finish);}catch(Exception e){file.delete();return false;}
 return true;}catch(Exception e){return false;}}
 @JavascriptInterface public void stopTracking(){runOnUiThread(()->{if(trusted(web.getUrl())){pendingTrip=null;pendingOwner=null;pendingEpoch=null;TrackingService.forget(MainActivity.this);stopService(new Intent(MainActivity.this,TrackingService.class));}});}}
 void launchTracking(){if(pendingTrip==null||pendingOwner==null||pendingEpoch==null)return;Intent i=new Intent(this,TrackingService.class);i.putExtra("trip",pendingTrip);i.putExtra("owner",pendingOwner);i.putExtra("epoch",pendingEpoch);try{startForegroundService(i);}catch(Exception e){Toast.makeText(this,"Não foi possível iniciar GPS em segundo plano.",Toast.LENGTH_LONG).show();}pendingTrip=null;pendingOwner=null;pendingEpoch=null;}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(code==20){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)launchTracking();else{TrackingService.blockedEpoch=pendingEpoch;TrackingService.authorization(MainActivity.this).edit().putString("blockedEpoch",pendingEpoch).commit();pendingTrip=null;pendingOwner=null;pendingEpoch=null;Toast.makeText(this,"Permita localização precisa para rastrear a viagem.",Toast.LENGTH_LONG).show();}}}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==12&&fileCallback!=null){Uri[] out=null;if(result==RESULT_OK){if(data!=null&&data.getData()!=null)out=new Uri[]{data.getData()};else if(cameraUri!=null)out=new Uri[]{cameraUri};}fileCallback.onReceiveValue(out);fileCallback=null;cameraUri=null;}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
}